  // Hand-counted: keeper 3, lamp 3, night 2, tower 2. The remaining content
  // words (climbed, hand, lit, old, older, shook, storm) occur once each.
  assert.deepEqual(topWords(PASSAGE, 4), [
    { word: 'keeper', count: 3 },
    { word: 'lamp', count: 3 },
    { word: 'night', count: 2 },
    { word: 'tower', count: 2 },
  ]);
});

